"""Capped retry helpers for sequential pipelines."""

RETRYABLE_PREFIX = 500


def should_retry(status):
    return status >= 400


def backoff(attempt):
    return 50 * (2 ** attempt)


def run_chain(steps, value):
    acc = value
    for step in steps:
        acc = step(acc)
    return acc

